import java.io.*;
import java.nio.file.*;

public class HighPerformanceIO {

    public void processLargeFile(Path inputPath, Path outputPath) throws IOException {
        // Java 9+ allows effectively final resources in try-with-resources
        // Here we instantiate the buffered streams directly in the resource block for automatic, safe closure
        try (BufferedReader reader = Files.newBufferedReader(inputPath);
             BufferedWriter writer = Files.newBufferedWriter(outputPath)) {

            String line;
            while ((line = reader.readLine()) != null) {
                // Process and write data via buffer
                writer.write(line.toUpperCase());
                writer.newLine();
            }
            // Explicit flush is not strictly required before close, 
            // as BufferedWriter's close() automatically flushes the buffer.
        } catch (IOException e) {
            // Accessing suppressed exceptions if any occurred during automatic close
            for (Throwable suppressed : e.getSuppressed()) {
                System.err.println("Suppressed exception during resource cleanup: " + suppressed.getMessage());
            }
            throw e;
        }
    }
}
